"""
Translate the program to its modules and serialize each, its bytes in the result where dart writes
a file (CodegenResult). A compile that is not standalone also generates the JS runtime that loads
the modules (js/runtime_generator.dart) and the support JS that tests the engine's features, each
held by the file name dart writes it to (io_util.dart's writeJsRuntime and writeSupportJs).
"""
@parity "dart2wasm/lib/compile.dart:572 _runCodegenPhase" function _run_codegen_phase(tfa_success::TfaResult, options::WasmCompilerOptions)::CodegenResult
    local at = "dart2wasm/lib/compile.dart:572 _runCodegenPhase"
    # dart writes each module's source map beside it, its URL from the file manager's generator; a
    # library compile has no file to name, so source maps wait for a caller that asks for them
    options.translator_options.generate_source_maps &&
        reject!(Unquarantined("src/compile.jl _runCodegenPhase: source maps, whose URL a library compile has no file to give"), at)
    local module_output_data = build_module_output_data(tfa_success.module_strategy)
    local translator = Translator(tfa_success.component, module_output_data, options.translator_options)
    local modules = translate(translator, nothing)
    local wasm_files = LinkedHashMap{String,Vector{UInt8}}()
    for (module_metadata, module_) in modules
        module_metadata.skip_emit && continue
        local serializer = WasmBuilder.Serializer()
        WasmBuilder.serialize(serializer, module_)
        wasm_files[module_metadata.module_name] = WasmBuilder.data(serializer)
    end
    local js_files = LinkedHashMap{String,String}()
    if !options.translator_options.standalone
        local js_runtime_finalizer = JS.RuntimeFinalizer(translator.interop_member_namer[])
        local js_runtime = generate(js_runtime_finalizer,
            main_module(module_output_data).module_import_name,
            translated_procedures(translator.functions[]),
            translator.internalized_strings_for_js_runtime,
            translator.options.require_js_string_builtin,
            translator.options.enable_deferred_loading || translator.options.enable_multi_module_stress_test_mode)
        local support_js = _generate_support_js(options.translator_options)
        # dart's path.setExtension: the output file without its extension, then the new one
        local stem = first(splitext(options.output_file))
        js_files["$stem.mjs"] = js_runtime
        js_files["$stem.support.js"] = support_js
    end
    local wasm_output_filename = basename(options.output_file)
    # dart asserts each module's name has an id (`idForModuleName(...)!`): a name with none rejects, located
    local module_ids = Set{Int}()
    for m in keys(modules)
        local id = WasmCompilerOptions_id_for_module_name(wasm_output_filename, m.module_name)
        id === nothing && reject!(Internal("$at: the module name $(m.module_name) has no id beside $wasm_output_filename"), at)
        push!(module_ids, id)
    end
    return CodegenResult(options.output_file, module_ids, wasm_files, js_files)
end

"""
Run wasm-opt over each module to optimize (the options' ids, else every emitted module's), with
dart's flags, toolchain annotations stripped as asked, and `-g` unless the names are stripped
(io_util.dart's runWasmOpt); dart also emits module names, a flag wasm-opt 130 lacks (below). dart runs the modules in a pool of processes; here
one after the other. dart's saveUnopt copies the unoptimized file aside; the CodegenResult a caller
holds is that module's bytes. A failure of wasm-opt rejects, located (src/julia/wasm_opt.jl).
"""
@parity "dart2wasm/lib/compile.dart:711 _runOptPhase" function _run_opt_phase(codegen_result::CodegenResult, options::WasmCompilerOptions)::OptResult
    local at = "dart2wasm/lib/compile.dart:711 _runOptPhase"
    local module_ids_to_optimize = isempty(options.module_ids_to_optimize) ? codegen_result.module_ids : options.module_ids_to_optimize
    local num_modules = length(module_ids_to_optimize)
    local wasm_opt_flags = String[(use_multi_module_opt(options) ? _binaryen_flags_multi_module() : _binaryen_flags())...]
    options.strip_toolchain_annotations && push!(wasm_opt_flags, "--strip-toolchain-annotations")
    # dart passes --emit-module-names, which keeps the module's name in the name section; wasm-opt 130,
    # Binaryen_jll's newest and the one pinned (dev/PARITY_MASTER.md), predates it, dart's binaryen
    # rev being newer: the one gap, the name section alone, the code untouched
    options.strip_wasm || push!(wasm_opt_flags, "-g")
    local wasm_files = LinkedHashMap{String,Vector{UInt8}}()
    for module_id in sort!(collect(module_ids_to_optimize))
        local name = WasmCompilerOptions_module_name_for_id(codegen_result.main_wasm_file, module_id)
        local bytes = get(codegen_result.wasm_files, name, nothing)
        bytes === nothing && reject!(Internal("$at: no module $name was emitted"), at)
        options.translator_options.verbose && println("Running wasm-opt $wasm_opt_flags on $name")
        wasm_files[name] = run_wasm_opt(bytes, wasm_opt_flags, at)
    end
    return OptResult(options.output_file, num_modules, wasm_files)
end

# deferred loading is out of scope (dev/PARITY_MASTER.md): its strategy and the multi-module stress
# test's reject, located; every other compile takes the default strategy, one module
@parity "dart2wasm/lib/compile.dart:747 _createModuleStrategy" function _create_module_strategy(options::WasmCompilerOptions, component::NirWorld)::ModuleStrategy
    local at = "dart2wasm/lib/compile.dart:747 _createModuleStrategy"
    options.translator_options.enable_deferred_loading && reject!(Unquarantined("src/compile.jl: deferred loading, out of scope (dev/PARITY_MASTER.md)"), at)
    options.translator_options.enable_multi_module_stress_test_mode && reject!(Unquarantined("src/compile.jl: the multi-module stress test, out of scope (dev/PARITY_MASTER.md)"), at)
    return DefaultModuleStrategy(options)
end

